def factorial(n):
    # Base case: stops the recursion
    if n <= 1:
        return 1
    # Recursive case: shrinks the problem
    return n * factorial(n - 1)


for i in range(1, 7):
    print(f'{i}! = {factorial(i)}')

class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, value):
        new_node = Node(value)
        if not self.head:
            self.head = new_node
            return
        current = self.head
        while current.next:
            current = current.next
        current.next = new_node

